Lemma room_tab : forall i kk j (E E' : env) sl l0 CL n (nx : nat),
  CH2.ret_of GD.RETS i kk = Some j ->
  lo i <= sl - l0 <= hi i n (uv E (EVar 12)) (uv E (EVar 33)) (uv E (EVar 66)) (uv E (EVar 69)) ->
  (needs i = 67%nat -> 1 <= uv E' (EVar 66) <= 400) -> (needs i = 70%nat -> 3 <= uv E' (EVar 69) <= 24) ->
  (F3i i = true -> 1 <= (uv E' (EVar 11) + uv E' (EVar 12)) mod 2 ^ 64 <= 17 /\ 0 <= uv E' (EVar 12) <= 16) ->
  (F6i i = true -> 25 <= uv E' (EVar 66) <= 41 /\ 1 <= uv E' (EVar 33) <= 17) ->
  (forall v, (v < nx)%nat -> uv E' (EVar v) = uv E (EVar v)) -> (needs i <= nx)%nat -> (48 <= nx)%nat ->
  l0 + 27 <= CL -> 1 <= n <= 21 -> 0 <= uv E (EVar 66) < 2 ^ 64 -> uv E (EVar 11) = n ->
